/**
 * Small deterministic offline actions for frequent UI intents.
 *
 * These are NOT generated by a language model. Keeping these separate
 * makes simple greetings responsive even when WebGPU is unavailable or a
 * model has not yet downloaded.
 */
export type InstantAnswer = { text: string; kind: 'instant' };

export function instantAnswer(text: string): InstantAnswer | null {
  const normalized = text.trim().toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[!?.,;:]+/g, ' ')
    .replace(/\s+/g, ' ').trim();

  const reply = (answer: string): InstantAnswer => ({ text: answer, kind: 'instant' });

  if (/^(oi+|oie+|ola+|e ai|eae|hey|hello|hi|opa)$/.test(normalized)) {
    return reply('Oi! Eu sou a REZ A.I. Posso conversar, ajudar com programação e consultar os documentos que você adicionar à memória. Para perguntas mais completas, preciso carregar um modelo aberto no seu dispositivo uma vez.');
  }
  if (/^(bom dia|boa tarde|boa noite)$/.test(normalized)) {
    return reply('Olá! Como posso ajudar você hoje? Posso ajudar com estudos, código e documentos locais.');
  }
  if (/^(tudo bem|tudo bom|como vai|como voce esta|como vc ta|como voce ta|como vc esta|como c ta|como ta|ta tudo bem|vc ta bem|ta funcionando|voce funciona)$/.test(normalized)) {
    return reply('Estou disponível! Estas mensagens simples são respondidas instantaneamente pelo aplicativo. Para perguntas mais complexas, a REZ utiliza um modelo aberto no próprio dispositivo.');
  }
  if (/^(obrigado|obrigada|valeu|vlw|brigado|brigada)$/.test(normalized)) {
    return reply('Por nada! Quando quiser, é só enviar sua próxima pergunta.');
  }
  if (/^(ajuda|help|o que voce faz|o que consegue fazer|quais suas funcoes)$/.test(normalized)) {
    return reply('Sou a REZ A.I, um aplicativo de chat local. Posso ajudar com programação, explicações, escrita e documentos. Ao adicionar arquivos em Memória, busco trechos relevantes no próprio navegador. Respostas generativas exigem baixar um modelo aberto e usar RAM/CPU/GPU do dispositivo.');
  }
  return null;
}
